import io.xeros.*;import io.xeros.content.*;import io.xeros.content.bosses.*;import io.xeros.content.bosses.wildypursuit.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;
public class BossRewardCapacity69Check{static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){Player p=WeaponsEquipment69Check.actor();p.getItems().addItem(4151,28);ok(p.getItems().freeSlots()==0,"Full inventory");return p;}static void reload(Player p,int id)throws Exception{ok(p.getItems().bankContains(id),"Reward not banked "+id);ok(PlayerSave.saveGameInstant(p),"Save reward");Player q=WeaponsEquipment69Check.actor();q.setLoginName(p.getLoginName());ok(PlayerSave.loadGame(q,p.getLoginName(),"IsolatedAudit",true).toString().equals("SUCCESS")&&q.getItems().bankContains(id),"Banked reward reload "+id);SkillsAuditCheck.clear(q);PlayerHandler.players[1]=p;ToaSoloPlayableCheck.clear(p);}public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();Player p=actor();BossRoutesCheck.at(p,3027,5233,0);Kratos.rewardPlayers();reload(p,7302);p=actor();BossRoutesCheck.at(p,3186,4622,0);Tarn.rewardPlayers();reload(p,9722);p=actor();Hunllef h=new Hunllef(p);h.add(p);Hunllef.rewardPlayers(p);reload(p,23776);p=actor();BossRoutesCheck.at(p,3195,3888,0);p.setIceQueenDamageCounter(80);FragmentOfSeren.rewardPlayers();reload(p,6792);
 p=actor();p.getHealth().setMaximumHealth(5000);p.getHealth().reset();BossRoutesCheck.at(p,1665,5928,0);NPC n=NPCHandler.getNpc(1101);n.spawnedBy=p.getIndex();n.killedBy=p.getIndex();n.appendDamage(p,n.getHealth().getCurrentHealth(),io.xeros.content.combat.Hitmark.HIT);for(int i=0;i<45&&!n.needRespawn&&!n.isUnregister();i++)Server.npcHandler.getNpcProcess().process(n.getIndex());ok(p.seaSnakeKills==1&&!p.getItems().getBankItems().isEmpty(),"Native Sea snake death/rewards with full bag");int hp=p.getHealth().getCurrentHealth();new io.xeros.content.commands.all.Solo().execute(p,"solo","home");SkillsAuditCheck.tick(8);ok(p.getHealth().getCurrentHealth()==hp,"Sea snake explosion followed exit");ok(PlayerSave.saveGameInstant(p),"Sea snake reward save");System.out.println("FIVE_BOSSES_FULL_INVENTORY_BANK_REWARDS_REAL_RELOAD_SEA_SNAKE_NATIVE_DEATH_AND_POST_EXIT_HAZARD_PASS");System.exit(0);}}
